    "src/keys.mjs": "export var UNSAFE_KEYS = ['__proto__', 'constructor', 'prototype'];\nexport function isUnsafeKey(key) {\n  return UNSAFE_KEYS.includes(String(key));\n}\nexport function assertSafeKey(key) {\n  if (isUnsafeKey(key)) throw new Error('unsafe key');\n}\n",
    "src/clone.mjs": "import { isUnsafeKey } from './keys.mjs';\n\nfunction isPlainObject(val) {\n  if (val === null || typeof val !== 'object') return false;\n  if (Array.isArray(val)) return false;\n  var proto = Object.getPrototypeOf(val);\n  return proto === Object.prototype || proto === null;\n}\n\nexport function deepClone(value) {\n  if (value === null) return null;\n  if (typeof value === 'string') return value;\n  if (typeof value === 'boolean') return value;\n  if (typeof value === 'number') {\n    if (!Number.isFinite(value)) throw new Error('non-finite number');\n    return value;\n  }\n  if (typeof value === 'undefined' || typeof value === 'function' ||\n      typeof value === 'symbol' || typeof value === 'bigint') {\n    throw new Error('unsupported type: ' + typeof value);\n  }\n  if (Array.isArray(value)) {\n    var result = [];\n    for (var i = 0; i < value.length; i++) {\n      result.push(deepClone(value[i]));\n    }\n    return result;\n  }\n  if (!isPlainObject(value)) {\n    throw new Error('non-plain object');\n  }\n  var result = {};\n  var keys = Object.keys(value);\n  for (var i = 0; i < keys.length; i++) {\n    var key = keys[i];\n    if (isUnsafeKey(key)) throw new Error('unsafe key: ' + key);\n    result[key] = deepClone(value[key]);\n  }\n  return result;\n}\n",
    "src/merge.mjs": "import { isUnsafeKey } from './keys.mjs';\nimport { deepClone } from './clone.mjs';\n\nfunction isPlainObject(val) {\n  if (val === null || typeof val !== 'object') return false;\n  if (Array.isArray(val)) return false;\n  var proto = Object.getPrototypeOf(val);\n  return proto === Object.prototype || proto === null;\n}\n\nexport function deepMerge(target, source) {\n  if (!isPlainObject(target)) throw new Error('target must be a plain object');\n  if (!isPlainObject(source)) throw new Error('source must be a plain object');\n  var result = {};\n  var targetKeys = Object.keys(target);\n  for (var i = 0; i < targetKeys.length; i++) {\n    var key = targetKeys[i];\n    if (isUnsafeKey(key)) throw new Error('unsafe key: ' + key);\n    result[key] = deepClone(target[key]);\n  }\n  var sourceKeys = Object.keys(source);\n  for (var i = 0; i < sourceKeys.length; i++) {\n    var key = sourceKeys[i];\n    if (isUnsafeKey(key)) throw new Error('unsafe key: ' + key);\n    if (key in result && isPlainObject(result[key]) && isPlainObject(source[key])) {\n      result[key] = deepMerge(target[key], source[key]);\n    } else {\n      result[key] = deepClone(source[key]);\n    }\n  }\n  return result;\n}\n",
    "src/index.mjs": "export { UNSAFE_KEYS, isUnsafeKey, assertSafeKey } from './keys.mjs';\nexport { deepClone } from './clone.mjs';\nexport { deepMerge } from './merge.mjs';\n\nimport { isUnsafeKey } from './keys.mjs';\nimport { deepClone } from './clone.mjs';\nimport { deepMerge } from './merge.mjs';\n\nfunction isPlainObject(val) {\n  if (val === null || typeof val !== 'object') return false;\n  if (Array.isArray(val)) return false;\n  var proto = Object.getPrototypeOf(val);\n  return proto === Object.prototype || proto === null;\n}\n\nexport function setPath(obj, path, value) {\n  if (!isPlainObject(obj)) throw new Error('obj must be a plain object');\n  if (typeof path !== 'string' || path === '') throw new Error('path must be a non-empty string');\n  var parts = path.split('.');\n  for (var i = 0; i < parts.length; i++) {\n    if (parts[i] === '') throw new Error('path segment must be non-empty');\n    if (isUnsafeKey(parts[i])) throw new Error('unsafe key in path');\n  }\n  var clonedValue = deepClone(value);\n\n  function setAt(current, idx) {\n    var result = {};\n    var keys = Object.keys(current);\n    for (var k = 0; k < keys.length; k++) {\n      result[keys[k]] = current[keys[k]];\n    }\n    var segment = parts[idx];\n    if (idx === parts.length - 1) {\n      result[segment] = clonedValue;\n    } else {\n      var next = result[segment];\n      if (next === undefined || next === null) {\n        result[segment] = setAt({}, idx + 1);\n      } else if (isPlainObject(next)) {\n        result[segment] = setAt(next, idx + 1);\n      } else {\n        throw new Error('intermediate value is not a plain object');\n      }\n    }\n    return result;\n  }\n\n  return setAt(obj, 0);\n}\n\nexport function mergeConfig(base, override) {\n  if (!isPlainObject(base)) throw new Error('base must be a plain object');\n  if (!isPlainObject(override)) throw new Error('override must be a plain object');\n  return deepMerge(base, override);\n}\n"
